<x-app-layout>
    <x-slot name="header"><div class="d-flex flex-column flex-lg-row align-items-lg-end justify-content-between gap-3"><div><div class="d-flex align-items-center gap-2 mb-2"><span class="cricket-live-dot"></span><span class="small text-uppercase fw-bold text-danger" style="letter-spacing:.12em;">Live draft room</span></div><h1 class="display-6 fw-bold mb-2">{{ $tournament->name }}</h1><p class="text-secondary mb-0">Captain view · Your selection is validated server-side.</p></div><div class="d-flex gap-2"><a href="{{ route('captain.reports.index', $tournament) }}" class="btn btn-outline-success"><i class="fa-solid fa-file-lines me-2"></i>Reports</a><a href="{{ route('captain.dashboard') }}" class="btn btn-light"><i class="fa-solid fa-arrow-left me-2"></i>Workspace</a></div></div></x-slot>

    <div class="container pb-5" x-data="captainDraft(@js($state), @js(route('captain.draft.state', $tournament)), @js(route('captain.draft.pick', $tournament)))" x-init="init()">
        <div class="row g-4 mb-4"><div class="col-xl-8"><div class="cricket-pitch-panel p-4 p-lg-5 h-100"><div class="d-flex align-items-start justify-content-between gap-3 mb-5"><div><p class="cricket-kicker mb-2">On the clock</p><div class="small text-white-50 mb-2" x-text="state.current_round ? `Round ${state.current_round} · Pick ${state.current_pick_number ?? '—'}` : 'Waiting for the next assignment'"></div><h2 class="display-5 fw-bold mb-1" x-text="state.current_team?.name ?? 'Waiting for admin'"></h2><div class="text-white-50" x-text="state.status === 'expired' ? 'Timer expired — waiting for admin action' : (state.captain_can_pick ? 'Your team can pick now.' : 'Waiting for your team turn.')"></div></div><span class="badge" style="background:var(--cricket-lime); color:var(--cricket-pitch-deep);" x-text="state.status"></span></div><div class="row align-items-end"><div class="col-md-7"><div class="small text-white-50 mb-1">Time remaining</div><div class="display-1 fw-bold" style="color:var(--cricket-lime);" x-text="formattedTimer"></div></div><div class="col-md-5 mt-3 mt-md-0"><div class="small text-white-50 mb-2">Draft progress</div><div class="d-flex justify-content-between small mb-2"><span x-text="`${state.summary?.selected ?? 0} selected`"></span><span x-text="`${state.summary?.total ?? 0} picks`"></span></div><div class="progress" style="height:.55rem; background:rgba(255,255,255,.15);"><div class="progress-bar" style="background:var(--cricket-lime);" :style="`width: ${state.summary?.total ? ((state.summary.selected / state.summary.total) * 100) : 0}%`"></div></div></div></div><div class="alert mt-4 mb-0 border-0" :class="state.captain_can_pick ? 'bg-white text-dark' : 'bg-dark bg-opacity-25 text-white'" x-text="state.captain_can_pick ? 'Your team is on the clock. Choose a player below.' : (state.status === 'expired' ? 'The timer has expired. Ask the admin to extend the pick or skip it before selecting.' : 'The board is live. You can select only when your team is assigned the active pick.')"></div></div></div><div class="col-xl-4"><div class="cricket-surface p-4 h-100"><p class="cricket-kicker mb-2">Your squad board</p><h2 class="h4 fw-bold mb-4">Draft status</h2><div class="vstack gap-3"><div class="cricket-surface-soft p-3 d-flex justify-content-between"><span class="text-secondary">Selected</span><strong class="text-success" x-text="state.summary?.selected ?? 0"></strong></div><div class="cricket-surface-soft p-3 d-flex justify-content-between"><span class="text-secondary">Remaining picks</span><strong x-text="Math.max(0, (state.summary?.total ?? 0) - (state.summary?.selected ?? 0))"></strong></div><div class="cricket-surface-soft p-3 d-flex justify-content-between"><span class="text-secondary">Available players</span><strong x-text="state.available_players.length"></strong></div></div><div class="small text-secondary mt-4"><i class="fa-solid fa-shield-halved text-success me-2"></i>Every pick is checked again by the server before it is recorded.</div><div class="border-top mt-4 pt-4"><div class="d-flex justify-content-between align-items-center mb-3"><div><p class="cricket-kicker mb-1">Your team</p><h3 class="h5 fw-bold mb-0" x-text="state.captain_team?.name ?? 'Assigned team'"></h3></div><span class="badge text-bg-success" x-text="`${captainTeamPlayers.length} picked`"></span></div><div class="vstack gap-2" x-show="captainTeamPlayers.length"><template x-for="player in captainTeamPlayers" :key="player.pick_number"><div class="cricket-surface-soft p-3 d-flex align-items-center gap-3"><span class="badge rounded-circle text-bg-success p-2" x-text="player.pick_number"></span><div class="flex-grow-1 min-w-0"><div class="fw-bold text-truncate" x-text="player.full_name"></div><div class="small text-secondary" x-text="player.playing_role || 'Unassigned role'"></div></div><div class="small text-secondary text-end" x-text="player.selected_at ? new Date(player.selected_at).toLocaleTimeString([], {hour: '2-digit', minute: '2-digit'}) : ''"></div></div></template></div><div class="small text-secondary text-center py-3" x-show="!captainTeamPlayers.length">No player picked yet.</div></div></div></div></div>

        <div class="row g-4"><div class="col-xl-7"><div class="cricket-surface p-4 p-lg-5 h-100"><div class="d-flex align-items-start justify-content-between gap-3 mb-4"><div><p class="cricket-kicker mb-2">Player pool</p><h2 class="h3 fw-bold mb-1">Available players</h2><p class="text-secondary mb-0">Approved and unselected players only.</p></div><span class="badge text-bg-light" x-text="`${state.available_players.length} available`"></span></div><div class="d-flex flex-column flex-md-row align-items-md-end justify-content-between gap-3 mb-3"><div class="d-flex align-items-center gap-2"><label class="small fw-bold text-secondary mb-0" for="captain-role-filter">Filter by role</label><select id="captain-role-filter" class="form-select form-select-sm" style="min-width:12rem;" x-model="roleFilter"><template x-for="filter in roleFilters" :key="filter.value"><option :value="filter.value" x-text="filter.label"></option></template></select></div><span class="small text-secondary" x-text="`${filteredPlayers.length} shown`"></span></div><div class="cricket-surface-soft p-3" style="max-height:34rem; overflow-y:auto;"><div class="row g-2"><template x-for="player in filteredPlayers" :key="player.id"><div class="col-md-6"><button type="button" class="btn btn-light w-100 text-start p-3 h-100" @click="confirmPick(player)" :disabled="!state.captain_can_pick || loading"><span class="d-flex align-items-center gap-3"><span class="cricket-brand-mark flex-shrink-0" style="width:2.25rem;height:2.25rem;"><i class="fa-solid fa-user"></i></span><span class="flex-grow-1 min-w-0"><span class="d-block fw-bold text-truncate" x-text="player.full_name"></span><span class="d-block small text-secondary" x-text="player.playing_role || 'Unassigned'"></span></span><i class="fa-solid fa-arrow-right text-success"></i></span></button></div></template></div><div class="text-center text-secondary py-4" x-show="!filteredPlayers.length"><i class="fa-solid fa-filter-circle-xmark fs-4 mb-2"></i><div>No players match this role.</div></div></div><div class="alert alert-light border mt-4 mb-0 small"><i class="fa-solid fa-circle-info text-success me-2"></i>Click a player to review and confirm your selection.</div></div></div><div class="col-xl-5"><div class="cricket-surface p-4 p-lg-5 h-100"><div class="d-flex justify-content-between align-items-start gap-3 mb-4"><div><p class="cricket-kicker mb-2">Live history</p><h2 class="h3 fw-bold mb-1">Pick sequence</h2></div><span class="small text-secondary">Revision <span x-text="state.revision"></span></span></div><div class="vstack gap-2"><template x-for="pick in state.picks" :key="pick.pick_number"><div class="cricket-surface-soft p-3 d-flex align-items-center gap-3"><span class="badge rounded-circle p-2" :class="pick.status === 'selected' ? 'text-bg-success' : (pick.status === 'active' ? 'text-bg-warning' : 'text-bg-light')" x-text="pick.pick_number"></span><div class="flex-grow-1 min-w-0"><div class="fw-bold text-truncate" x-text="pick.team?.name"></div><div class="small text-secondary text-truncate" x-text="pick.player?.full_name || (pick.status === 'active' ? 'On the clock' : pick.status)"></div></div><i class="fa-solid" :class="pick.status === 'selected' ? 'fa-check text-success' : 'fa-ellipsis text-secondary'"></i></div></template></div></div></div></div>
        <div class="alert alert-danger border-0 shadow-sm mt-4" x-show="error" x-text="error"></div>

        <div class="modal fade" id="pickConfirmationModal" tabindex="-1" aria-hidden="true" x-ref="pickModal"><div class="modal-dialog modal-dialog-centered"><div class="modal-content border-0 shadow-lg"><div class="modal-header border-0 p-4"><div><p class="cricket-kicker mb-1">Confirm selection</p><h5 class="modal-title fw-bold">Make this pick?</h5></div><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body px-4 pb-4"><div class="cricket-surface-soft p-4 d-flex align-items-center gap-3"><span class="cricket-brand-mark"><i class="fa-solid fa-user"></i></span><div><div class="h5 fw-bold mb-1" x-text="selectedPlayer?.full_name"></div><div class="small text-secondary" x-text="selectedPlayer?.playing_role || 'Player'"></div></div></div><p class="small text-secondary mt-3 mb-0">This action will be recorded in the draft history and the board will advance if the pick is accepted.</p></div><div class="modal-footer border-0 px-4 pb-4"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancel</button><button type="button" class="btn btn-success" @click="submitPick()" :disabled="loading">Confirm pick <i class="fa-solid fa-check ms-2"></i></button></div></div></div></div>
    </div>

    <script>
        function captainDraft(initialState, stateUrl, pickUrl) {
            return {
                state: initialState, stateUrl, pickUrl, selectedPlayer: null, loading: false, error: '', roleFilter: 'all', remaining: initialState.timer?.remaining_seconds ?? null, timerDeadline: initialState.timer?.expires_at ? Date.parse(initialState.timer.expires_at) : null, serverOffsetMs: initialState.timer?.server_now ? Date.parse(initialState.timer.server_now) - Date.now() : 0, timerHandle: null, pollHandle: null,
                init() { this.syncTimer(); this.timerHandle = window.setInterval(() => this.syncTimer(), 250); this.pollHandle = window.setInterval(() => this.poll(), 2000); },
                syncTimer() { if (this.timerDeadline === null || !['live', 'expired'].includes(this.state.status)) return; this.remaining = Math.max(0, Math.ceil((this.timerDeadline - (Date.now() + this.serverOffsetMs)) / 1000)); },
                syncServerClock(payload, requestStartedAt = null, responseReceivedAt = null) { const serverNow = payload.timer?.server_now ? Date.parse(payload.timer.server_now) : null; if (Number.isFinite(serverNow)) { const midpoint = requestStartedAt !== null && responseReceivedAt !== null ? (requestStartedAt + responseReceivedAt) / 2 : Date.now(); this.serverOffsetMs = serverNow - midpoint; } },
                get roleFilters() { return [{ value: 'all', label: 'All roles' }, { value: 'Batter', label: 'Batters' }, { value: 'Bowler', label: 'Bowlers' }, { value: 'All-rounder', label: 'All-rounders' }, { value: 'Wicketkeeper', label: 'Wicketkeepers' }, { value: 'Unassigned', label: 'Unassigned' }]; },
                get filteredPlayers() { if (this.roleFilter === 'all') return this.state.available_players; return this.state.available_players.filter(player => (player.playing_role || 'Unassigned') === this.roleFilter); },
                get captainTeamPlayers() { const teamId = this.state.captain_team?.id; return this.state.team_squads?.find(team => team.id === teamId)?.selected_players ?? []; },
                get formattedTimer() { if (this.remaining === null) return '--:--'; return `${Math.floor(this.remaining / 60).toString().padStart(2, '0')}:${Math.floor(this.remaining % 60).toString().padStart(2, '0')}`; },
                confirmPick(player) { this.selectedPlayer = player; bootstrap.Modal.getOrCreateInstance(this.$refs.pickModal).show(); },
                async submitPick() { if (!this.selectedPlayer) return; this.loading = true; this.error = ''; try { const response = await fetch(this.pickUrl, { method: 'POST', headers: { 'Accept': 'application/json', 'Content-Type': 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content }, body: JSON.stringify({ tournament_player_id: this.selectedPlayer.id }) }); const payload = await response.json(); if (!response.ok) { this.error = payload.message || Object.values(payload.errors || {}).flat()[0] || 'The pick could not be completed.'; return; } this.applyState(payload); bootstrap.Modal.getOrCreateInstance(this.$refs.pickModal).hide(); } catch (error) { this.error = 'The request failed. Please try again.'; } finally { this.loading = false; } },
                async poll() { if (document.hidden || this.loading) return; try { const requestStartedAt = Date.now(); const response = await fetch(this.stateUrl, { headers: { 'Accept': 'application/json' } }); const responseReceivedAt = Date.now(); if (!response.ok) return; const payload = await response.json(); this.syncServerClock(payload, requestStartedAt, responseReceivedAt); if (payload.revision !== this.state.revision) this.applyState(payload); } catch (error) { this.error = 'Live connection interrupted. Retrying automatically.'; } },
                applyState(payload) { this.state = payload; this.timerDeadline = payload.timer?.expires_at ? Date.parse(payload.timer.expires_at) : null; this.syncServerClock(payload); this.syncTimer(); },
            };
        }
    </script>
</x-app-layout>
